function resize(){const r=cv.getBoundingClientRect();const dpr=Math.min(2,window.devicePixelRatio||1);cv.width=Math.max(320,Math.floor(r.width*dpr));cv.height=Math.max(240,Math.floor(r.height*dpr));x.setTransform(dpr,0,0,dpr,0,0);viewW=r.width;viewH=r.height;scale=viewH/H}
