function box(px,py,w,h,fill,stroke){x.fillStyle=fill;x.fillRect(SX(px),SY(py),SW(w),SW(h));if(stroke){x.strokeStyle=stroke;x.lineWidth=Math.max(1,SW(2));x.strokeRect(SX(px),SY(py),SW(w),SW(h))}}
